import type { TaskFilters } from "@/hooks/useTasks";

export const taskKeys = {
  all: ["tasks"] as const,
  lists: () => [...taskKeys.all, "list"] as const,
  list: (projectId: string, filters?: TaskFilters) => [...taskKeys.lists(), projectId, filters] as const,
  details: () => [...taskKeys.all, "detail"] as const,
  detail: (taskId: string) => [...taskKeys.details(), taskId] as const,
  myTasks: (filters?: TaskFilters) => [...taskKeys.all, "my", filters] as const,
  stats: (projectId: string) => [...taskKeys.all, "stats", projectId] as const,
  comments: (taskId: string) => [...taskKeys.all, "comments", taskId] as const,
};

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { taskKeys } from "@/lib/queryKeys";
import type {
  Task,
  TaskComment,
  TaskCreateRequest,
  TaskUpdateRequest,
  TaskStatus,
  TaskPriority,
  TaskListResponse,
  TaskStats,
} from "@/types/api";

export interface TaskFilters {
  page?: number;
  page_size?: number;
  status?: string;
  assignee_id?: string;
  priority?: string;
}

export function useTasks(projectId: string, filters?: TaskFilters) {
  return useQuery<TaskListResponse>({
    queryKey: taskKeys.list(projectId, filters),
    queryFn: () => api.listTasks(projectId, filters),
    enabled: !!projectId,
  });
}

export function useTask(taskId: string) {
  return useQuery<Task>({
    queryKey: taskKeys.detail(taskId),
    queryFn: () => api.getTask(taskId),
    enabled: !!taskId,
  });
}

export function useMyTasks(filters?: TaskFilters) {
  return useQuery<TaskListResponse>({
    queryKey: taskKeys.myTasks(filters),
    queryFn: () => api.getMyTasks(filters),
  });
}

export function useProjectTaskStats(projectId: string) {
  return useQuery<TaskStats>({
    queryKey: taskKeys.stats(projectId),
    queryFn: () => api.getProjectTaskStats(projectId),
    enabled: !!projectId,
  });
}

export function useTaskComments(taskId: string) {
  return useQuery<TaskComment[]>({
    queryKey: taskKeys.comments(taskId),
    queryFn: () => api.listComments(taskId),
    enabled: !!taskId,
  });
}

export function useCreateTask(projectId: string) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (data: TaskCreateRequest) => api.createTask(projectId, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.myTasks() });
      queryClient.invalidateQueries({ queryKey: taskKeys.stats(projectId) });
    },
  });
}

export function useUpdateTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ taskId, data }: { taskId: string; data: TaskUpdateRequest }) =>
      api.updateTask(taskId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.detail(variables.taskId) });
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.myTasks() });
    },
  });
}

export function useDeleteTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.deleteTask,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: taskKeys.all });
    },
  });
}

export function useTransitionTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ taskId, toStatus }: { taskId: string; toStatus: TaskStatus }) =>
      api.transitionTask(taskId, toStatus),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.detail(data.id) });
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.myTasks() });
      queryClient.invalidateQueries({ queryKey: taskKeys.stats(data.project_id) });
    },
  });
}

export function useReorderTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ taskId, status, sortOrder }: { taskId: string; status: TaskStatus; sortOrder: number }) =>
      api.reorderTask(taskId, status, sortOrder),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.stats(data.project_id) });
    },
  });
}

export function useBulkUpdateStatus() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.bulkUpdateStatus,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: taskKeys.all });
    },
  });
}

export function useAssignTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ taskId, assigneeId }: { taskId: string; assigneeId: string }) =>
      api.assignTask(taskId, assigneeId),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.detail(data.id) });
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.myTasks() });
    },
  });
}

export function useUnassignTask() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.unassignTask,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.detail(data.id) });
      queryClient.invalidateQueries({ queryKey: taskKeys.lists() });
      queryClient.invalidateQueries({ queryKey: taskKeys.myTasks() });
    },
  });
}

export function useAddComment() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ taskId, content }: { taskId: string; content: string }) =>
      api.addComment(taskId, content),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: taskKeys.comments(variables.taskId) });
      queryClient.invalidateQueries({ queryKey: taskKeys.detail(variables.taskId) });
    },
  });
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import React from "react";
import { useTasks, useTask, useCreateTask, useUpdateTask, useTransitionTask, useMyTasks, useProjectTaskStats } from "../useTasks";
import { api } from "@/lib/api";

vi.mock("@/lib/api", () => ({
  api: {
    listTasks: vi.fn(),
    getTask: vi.fn(),
    createTask: vi.fn(),
    updateTask: vi.fn(),
    transitionTask: vi.fn(),
    getMyTasks: vi.fn(),
    getProjectTaskStats: vi.fn(),
  },
}));

const createWrapper = () => {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return ({ children }: { children: React.ReactNode }) =>
    React.createElement(QueryClientProvider, { client: queryClient }, children);
};

const mockTask = {
  id: "task-1",
  project_id: "proj-1",
  title: "Test Task",
  description: null,
  status: "todo" as const,
  priority: "medium" as const,
  assignee_id: null,
  due_date: null,
  sort_order: 0,
  created_by: "user-1",
  created_at: "2025-01-01T00:00:00Z",
  updated_at: "2025-01-01T00:00:00Z",
  assignee_name: null,
  created_by_name: "Admin",
  comment_count: 0,
};

describe("useTasks", () => {
  beforeEach(() => vi.clearAllMocks());

  it("returns task list", async () => {
    const response = { items: [mockTask], total: 1, page: 1, page_size: 20 };
    vi.mocked(api.listTasks).mockResolvedValue(response);

    const { result } = renderHook(() => useTasks("proj-1"), { wrapper: createWrapper() });

    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(result.current.data).toEqual(response);
    expect(api.listTasks).toHaveBeenCalledWith("proj-1", undefined);
  });
});

describe("useTask", () => {
  beforeEach(() => vi.clearAllMocks());

  it("returns single task", async () => {
    vi.mocked(api.getTask).mockResolvedValue(mockTask);

    const { result } = renderHook(() => useTask("task-1"), { wrapper: createWrapper() });

    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(result.current.data).toEqual(mockTask);
  });
});

describe("useCreateTask", () => {
  beforeEach(() => vi.clearAllMocks());

  it("calls POST with correct body", async () => {
    vi.mocked(api.createTask).mockResolvedValue(mockTask);

    const { result } = renderHook(() => useCreateTask("proj-1"), { wrapper: createWrapper() });

    result.current.mutate({ title: "New Task" });
    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(api.createTask).toHaveBeenCalledWith("proj-1", { title: "New Task" });
  });
});

describe("useUpdateTask", () => {
  beforeEach(() => vi.clearAllMocks());

  it("calls PATCH with correct endpoint", async () => {
    vi.mocked(api.updateTask).mockResolvedValue(mockTask);

    const { result } = renderHook(() => useUpdateTask(), { wrapper: createWrapper() });

    result.current.mutate({ taskId: "task-1", data: { title: "Updated" } });
    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(api.updateTask).toHaveBeenCalledWith("task-1", { title: "Updated" });
  });
});

describe("useTransitionTask", () => {
  beforeEach(() => vi.clearAllMocks());

  it("calls POST /transition with correct body", async () => {
    const transitioned = { ...mockTask, status: "in_progress" as const };
    vi.mocked(api.transitionTask).mockResolvedValue(transitioned);

    const { result } = renderHook(() => useTransitionTask(), { wrapper: createWrapper() });

    result.current.mutate({ taskId: "task-1", toStatus: "in_progress" });
    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(api.transitionTask).toHaveBeenCalledWith("task-1", "in_progress");
  });
});

describe("useMyTasks", () => {
  beforeEach(() => vi.clearAllMocks());

  it("calls correct endpoint", async () => {
    const response = { items: [mockTask], total: 1, page: 1, page_size: 20 };
    vi.mocked(api.getMyTasks).mockResolvedValue(response);

    const { result } = renderHook(() => useMyTasks(), { wrapper: createWrapper() });

    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(api.getMyTasks).toHaveBeenCalled();
  });
});

describe("useProjectTaskStats", () => {
  beforeEach(() => vi.clearAllMocks());

  it("calls correct endpoint", async () => {
    const stats = { todo: 2, in_progress: 1, done: 3, total: 6 };
    vi.mocked(api.getProjectTaskStats).mockResolvedValue(stats);

    const { result } = renderHook(() => useProjectTaskStats("proj-1"), { wrapper: createWrapper() });

    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(api.getProjectTaskStats).toHaveBeenCalledWith("proj-1");
    expect(result.current.data).toEqual(stats);
  });
});

